using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using System.Linq;using System.IO;
internal class CommandScript : IRunCommand {public void Execute(ExecutionResult result){
if(!EditorApplication.isPlaying && UnityEngine.SceneManagement.SceneManager.GetActiveScene().name!="CampusTerrain"){EditorSceneManager.SaveOpenScenes();EditorSceneManager.OpenScene("Assets/CampusSim/Scenes/CampusTerrain.unity");} var target=Object.FindObjectsByType<MeshFilter>(FindObjectsSortMode.None).Single(f=>f.name=="Photo inspired HiTech");
var original=AssetDatabase.LoadAssetAtPath<UnityEngine.Mesh>("Assets/CampusSim/Generated/HiTechFacade/Massing.asset");if(!original)throw new System.Exception("Missing immutable facade source");
var source=Object.Instantiate(original);var vertices=source.vertices;var world=vertices.Select(target.transform.TransformPoint).ToArray();float min=world.Min(v=>v.x),max=world.Max(v=>v.x);const float roadClearX=291f;
if(min<280||min>283||max<375||max>378)throw new System.Exception("Unexpected facade extents");
for(int i=0;i<vertices.Length;i++){var v=world[i];v.x=roadClearX+(v.x-min)*(max-roadClearX)/(max-min);vertices[i]=target.transform.InverseTransformPoint(v);}source.vertices=vertices;source.RecalculateNormals();source.RecalculateBounds();
const string path="Assets/CampusSim/Generated/HitechRoadRepair/Massing_road_clearance.asset";var mesh=AssetDatabase.LoadAssetAtPath<UnityEngine.Mesh>(path);if(!mesh){mesh=source;mesh.name="Massing_road_clearance";AssetDatabase.CreateAsset(mesh,path);}else{EditorUtility.CopySerialized(source,mesh);mesh.name="Massing_road_clearance";Object.DestroyImmediate(source);EditorUtility.SetDirty(mesh);}
Undo.RecordObject(target,"Fit road-facing facade");target.sharedMesh=mesh;var collider=target.GetComponent<MeshCollider>();Undo.RecordObject(collider,"Fit matching facade collider");collider.sharedMesh=null;collider.sharedMesh=mesh;Physics.SyncTransforms();AssetDatabase.SaveAssets();
if(!EditorApplication.isPlaying){EditorSceneManager.MarkSceneDirty(target.gameObject.scene);EditorSceneManager.SaveScene(target.gameObject.scene);}result.Log("FACADE_CLEARANCE min_x="+min+" -> "+roadClearX+" max_x_preserved="+max+" source_unchanged=true playing="+EditorApplication.isPlaying);
}}
